{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Lurasidone, a structurally similar fused lactam-piperazine antipsychotic, has an absolute oral bioavailability of 9–19% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "GSK1322322, a large basic molecule with a piperazine, has an absolute oral bioavailability of 57% in fasted healthy volunteers, supporting high F for large complex molecules.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (F below 20%) based on the strong structural analogy to lurasidone (F 9–19%) and other low-F heteroaromatic lactams, despite some high-F analogues with different scaffolds.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "The query's pyridopyrimidine-dione core is more polar than lurasidone's benzisothiazole, and its effect on absorption is unknown.",
    "The influence of the tetrahydronaphthyridine substituent on permeability and first-pass metabolism is not directly covered by the analogues."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C17"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fused lactam-piperazine antipsychotics"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C19"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "large basic piperazine-containing kinase inhibitors"
    }
  ],
  "revision_action": "initial"
}

